// CORE-6161: the assistant's own changes in this browser session, sent with each chat request.

export type SessionChangeKind = 'set_value' | 'confirm_field' | 'set_table_cell' | 'undo';

export interface SessionChange {
  field: string;
  label: string;
  from_display?: string;
  to_display?: string;
  kind: SessionChangeKind;
  at: string;
}

// What a screen handler reports about one changed field or cell (raw form values).
export interface SessionChangeDraft {
  field: string;
  label?: string;
  from?: unknown;
  to?: unknown;
  kind: Exclude<SessionChangeKind, 'undo'>;
  field_type?: string;
}

export const MAX_SESSION_CHANGES = 30;
const MAX_NAME_CHARS = 120;
const MAX_DISPLAY_CHARS = 200;

export const MASKED_DISPLAY = '•••• (masked)';

// Mirrors helpers/assistant_common/pii.py: names of identifiers and bank details.
const SENSITIVE_FRAGMENTS = [
  'iban',
  'vat',
  'ustid',
  'ust_id',
  'tax_id',
  'taxid',
  'tax_number',
  'email',
  'e_mail',
  'mail',
  'bank',
  'swift',
  'account_number',
];
const SENSITIVE_TOKENS = ['bic'];
const NUMERIC_TYPES = ['AMOUNT', 'NUMBER', 'NUMBERS_ONLY'];

const IBAN = /\b[A-Za-z]{2}\d{2}(?:[ ]?[A-Za-z0-9]){11,30}\b/;
const EMAIL = /[\w.%+-]+@[\w-]+(?:\.[\w-]+)+/;
const VAT_ID = /\b[A-Za-z]{2,3}\d{8,12}\b/;
const DIGIT_RUN = /\d+(?: \d+)*/g;
const MIN_MASKED_DIGITS = 9;

export function isSensitiveFieldName(name: string, fieldType?: string): boolean {
  if (fieldType && NUMERIC_TYPES.includes(fieldType.toUpperCase())) return false;
  const text = (name || '').toLowerCase();
  if (SENSITIVE_FRAGMENTS.some((fragment) => text.includes(fragment))) return true;
  return text.split(/[^a-z0-9]+/).some((token) => SENSITIVE_TOKENS.includes(token));
}

export function isSensitiveValue(text: string): boolean {
  if (IBAN.test(text) || EMAIL.test(text) || VAT_ID.test(text)) return true;
  for (const run of text.match(DIGIT_RUN) || []) {
    if (run.replace(/\D/g, '').length >= MIN_MASKED_DIGITS) return true;
  }
  return false;
}

function clip(text: string, max: number): string {
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

// The value as it may leave the browser: empty → undefined, sensitive → fully masked, capped.
export function maskDisplay(field: string, value: unknown, fieldType?: string): string | undefined {
  if (value === null || value === undefined || typeof value === 'object') return undefined;
  const text = String(value).replace(/\s+/g, ' ').trim();
  if (!text) return undefined;
  if (isSensitiveFieldName(field, fieldType) || isSensitiveValue(text)) return MASKED_DISPLAY;
  return clip(text, MAX_DISPLAY_CHARS);
}

export function toSessionChange(draft: SessionChangeDraft, at: Date = new Date()): SessionChange {
  const change: SessionChange = {
    field: clip(draft.field, MAX_NAME_CHARS),
    label: clip(draft.label || draft.field, MAX_NAME_CHARS),
    kind: draft.kind,
    at: at.toISOString(),
  };
  const from = maskDisplay(draft.field, draft.from, draft.field_type);
  const to = maskDisplay(draft.field, draft.to, draft.field_type);
  if (from !== undefined) change.from_display = from;
  if (to !== undefined) change.to_display = to;
  return change;
}

// An undo reverses the earlier entries for the same fields.
export function undoSessionChanges(changes: SessionChange[], at: Date = new Date()): SessionChange[] {
  return changes.map((change) => {
    const undo: SessionChange = {
      field: change.field,
      label: change.label,
      kind: 'undo',
      at: at.toISOString(),
    };
    if (change.to_display !== undefined) undo.from_display = change.to_display;
    if (change.from_display !== undefined) undo.to_display = change.from_display;
    return undo;
  });
}

export function capSessionChanges(changes: SessionChange[]): SessionChange[] {
  return changes.slice(-MAX_SESSION_CHANGES);
}

// The field key of a table cell; tokens let the API drop hidden columns.
export function tableCellKey(table: string, column: string, rowIndex: number): string {
  return `${table}.${column}.${rowIndex + 1}`;
}
